import math

import numpy as np
import torch
from torch.utils.data import Dataset
from sklearn.neighbors import KernelDensity

class SquareDummyDataset(Dataset):

    def __init__(self, seed = 42, size = 1000, transform=None, target_transform=None, dist = 'uniform', cache_targets = False, add_ellipsis = False, **kwargs):
        self.seed = seed
        self.size = size
        self.transform = transform
        self.target_transform = target_transform

        self.area_scale = 1000
        self.area_offset = 10

        self.add_ellipsis = add_ellipsis

        self.targets = self._get_target_values(dist)
        self.cache_targets = cache_targets
        self.cache = {}


    def __getitem__(self, index):

        target = self.targets[index]
        square_area = self.area_scale * (target + self.area_offset)
        img = self._generate_image(square_area, seed= index + self.seed)

        if self.transform:
            img = self.transform(img)

        meta = {'side_length' : int(math.sqrt(square_area)),
                'true_target': target}
   
        if self.target_transform and index not in self.cache:
            target = self.target_transform(target)

            if self.cache_targets:
                self.cache[index] = target

        elif index in self.cache:
            target = self.cache[index]


        target = target.unsqueeze(0)

        return img, target, meta


    def __len__(self):
        return self.size

    def _get_target_values(self, dist):

        generator = torch.Generator().manual_seed(self.seed)
        if dist == 'uniform':
            lower = -5
            upper = 30
            vals = torch.rand(self.size, generator=generator) * (upper - lower) + lower
            return vals.to(torch.float32)
        
        elif dist == 'gaussian':
            mean = 5.8
            std = 4.5
            vals = torch.normal(mean=mean, std=std, size=(self.size,), generator=generator)
            return vals.to(torch.float32)
        
        elif dist == 'template':
            kde = KernelDensity(bandwidth='scott', kernel='gaussian')
            kde.fit(np.asarray(TEMPLATE_VALUES)[:, None])
            vals = kde.sample(n_samples=self.size, random_state=self.seed)
            vals = torch.from_numpy(vals)
            vals = vals.squeeze()
            return vals.to(torch.float32)


    def _generate_image(self, square_area: int, img_size: tuple = (224, 224), seed = None):
        
        # Create black background
        img_height, img_width = img_size
        image = torch.zeros((img_height, img_width))

        side_length = int(math.sqrt(square_area))
        # Calculate position to center the square
        start_x = (img_width - side_length) // 2
        start_y = (img_height - side_length) // 2

        # Draw white square
        image[start_y:start_y + side_length, start_x:start_x + side_length] = 0.5

        if self.add_ellipsis:
            # Add uncorelated image feature
            n_range = (1, 20)
            shape_range = (6, 60)
            location_range = (0, 224)
            val_range = (0.05, 0.4)
            
            el_img = draw_random_elipsis(n_ellipis=n_range, shape=shape_range, location=location_range, fill_values=val_range, image_size=img_size, seed=seed)
            image = image + el_img

        # add channel dimension
        image = image.unsqueeze(0)
        image = image.to(dtype=torch.float32)

        return image
    


def draw_random_elipsis(n_ellipis: tuple, shape: tuple, location: tuple, fill_values: tuple,  image_size: tuple, seed = 42):

    gen = torch.Generator().manual_seed(seed)
    n = torch.randint(*n_ellipis, size=(1,), generator=gen)

    img = torch.zeros(image_size)
    for i in range(n):
        s = torch.randint(*shape, size=(2,), generator=gen)
        l = torch.randint(*location, size=(2,), generator=gen)
        fill_min, fill_max = fill_values
        v = torch.rand(1, generator=gen).item() * (fill_max - fill_min) + fill_min
        mask = make_ellipsis_mask(shape=s, location=l, mask_size=image_size)
        img[mask] = v

    return img



def make_ellipsis_mask(shape: tuple, location: tuple, mask_size: tuple):        
        H, W = mask_size
        h, w = shape
        cy, cx = location
        
        # Create coordinate grids
        y_coords, x_coords = torch.meshgrid(torch.arange(H), torch.arange(W), indexing='ij')
        
        # Create circular mask (ellipse with given height/width)
        mask = ((y_coords - cy).float()**2 / (h/2)**2 + (x_coords - cx).float()**2 / (w/2)**2) <= 1
        return mask


